const PRAKTIKA = [
  { id: 'p1', nr: '#1', titel: 'Uni-Schema anlegen, erste DQL', abgabe: '14.10.2026', intro: 'Kemper-Uni-Schema in DBPRAKT anlegen, erste Abfragen in DBPRAKT, RelaX und HyPer.',
    aufgaben: [
      { nr: '1.1', aufgabe: 'Erstelle das Kemper-„Uni“-Schema unter deinem Datenbank-Account in DBPRAKT (Relationen, Daten, Berechtigungen für DBMI60).', tipp: 'Reihenfolge beachten: erst die Relationen ohne Fremdschlüssel (Studenten, Professoren), dann die abhängigen. Verbindung: eduVPN → SQL Developer → Host 10.28.1.3, Port 1521, SID DBPRAKT.', loesung: '1) eduVPN starten, „Hochschule München via LRZ-VPN“, Profil HM-Netz\n2) SQL Developer: neue Verbindung, Benutzer = Team-Name (DBMIxx), Host 10.28.1.3, Port 1521, SID DBPRAKT, Test → Speichern\n3) Kennwort nur EINMAL pro Team zurücksetzen und im Team teilen\n4) Skripte „Kemper Schema“, „Kemper Daten“, „Berechtigungen“ ausführen (F5)\n5) Prüfen: SELECT table_name FROM user_tables; – Assistenten, Professoren, Studenten, Vorlesungen, hoeren, pruefen, voraussetzen\n6) Je Relation: GRANT SELECT ON <Relation> TO DBMI60;' },
      { nr: '1.2a', aufgabe: 'Zeige alle Professoren, deren Name mit A anfängt.', tipp: 'Platzhalter für „beliebig viele Zeichen“ beim Mustervergleich.', loesung: "SELECT * FROM Professoren WHERE Name LIKE 'A%';\n→ (2134, Augustinus, C3, 309)", db: 'uni', sql: "SELECT * FROM Professoren WHERE Name LIKE 'A%'" },
      { nr: '1.2b', aufgabe: 'Zeige alle Studenten aus dem ersten Semester.', tipp: 'Einfache Selektion – schau dir das Ergebnis genau an.', loesung: 'SELECT * FROM Studenten WHERE Semester = 1;\n→ leere Menge: In der Uni-DB ist niemand im 1. Semester (kleinstes Semester: 2). Das ist kein Fehler der Anfrage.', db: 'uni', sql: 'SELECT * FROM Studenten WHERE Semester = 1' },
      { nr: '1.3', aufgabe: 'Führe 2a und 2b in RelaX und HyPer aus.', tipp: 'RelaX: Datensatz „Kemper Datenbanksysteme“ wählen; Algebra mit σ.', loesung: "RelaX (Algebra): σ Name LIKE 'A%' (Professoren) · σ Semester = 1 (Studenten)\nRelaX (SQL-Reiter) und HyPer: dieselben SELECTs wie oben\nHyPer: https://hyper-db.de/interface.html – „Show Query Plan“ ansehen." },
    ] },
  { id: 'p2', nr: '#2', titel: 'Relationale Algebra und SQL', abgabe: '21.10.2026', intro: 'Jede Anfrage in relationaler Algebra und in SQL. Tipp: Explain Plan (F10), Ausführungsbaum in RelaX, Query Plan in HyPer.',
    aufgaben: [
      { nr: '2.1', aufgabe: 'Alle Studenten im zweiten Semester.', tipp: 'Nur Tupel filtern, alle Attribute behalten.', loesung: 'σ Semester=2 (Studenten)\nSELECT * FROM Studenten WHERE Semester = 2;\n→ Theophrastos (29120), Feuerbach (29555)', db: 'uni', sql: 'SELECT * FROM Studenten WHERE Semester = 2' },
      { nr: '2.2', aufgabe: 'Alle C4-Professoren.', tipp: 'Selektion auf Rang – Zeichenkette in Hochkommas.', loesung: "σ Rang='C4' (Professoren)\nSELECT * FROM Professoren WHERE Rang = 'C4';\n→ Sokrates, Russel, Curie, Kant", db: 'uni', sql: "SELECT * FROM Professoren WHERE Rang = 'C4'" },
      { nr: '2.3', aufgabe: 'Namen aller Professoren, die mit „S“ anfangen.', tipp: 'Erst selektieren, dann auf den Namen projizieren.', loesung: "π Name (σ Name LIKE 'S%' (Professoren))\nSELECT Name FROM Professoren WHERE Name LIKE 'S%';\n→ Sokrates", db: 'uni', sql: "SELECT Name FROM Professoren WHERE Name LIKE 'S%'" },
      { nr: '2.4', aufgabe: 'Alle Vorlesungstitel.', tipp: 'Projektion. Denk an die Mengensemantik der Algebra.', loesung: 'π Titel (Vorlesungen)\nSELECT DISTINCT Titel FROM Vorlesungen;\n→ 10 Titel. DISTINCT entspricht der Mengensemantik von π (hier ohne Auswirkung, da alle Titel verschieden).', db: 'uni', sql: 'SELECT DISTINCT Titel FROM Vorlesungen' },
      { nr: '2.5', aufgabe: 'Benenne die Relation Studenten in Studierenden um.', tipp: 'Umbenennung einer Relation; in SQL über einen Alias – oder dauerhaft per DDL.', loesung: 'ρ Studierenden (Studenten)\nSELECT * FROM Studenten Studierenden;  (Alias, Ergebnis wie Studenten)\nDauerhaft (Standard): ALTER TABLE Studenten RENAME TO Studierenden;\n(Oracle kennt zusätzlich RENAME Studenten TO Studierenden;)', db: 'uni', sql: 'SELECT Studierenden.* FROM Studenten Studierenden' },
      { nr: '2.6', aufgabe: 'Benenne das Attribut Titel in Vorlesungen in Vorlesungsname um.', tipp: 'Umbenennung eines Attributs: ρ neu←alt; in SQL mit AS.', loesung: 'ρ Vorlesungsname←Titel (Vorlesungen)\nSELECT VorlNr, Titel AS Vorlesungsname, SWS, gelesenVon FROM Vorlesungen;', db: 'uni', sql: 'SELECT VorlNr, Titel AS Vorlesungsname, SWS, gelesenVon FROM Vorlesungen' },
      { nr: '2.7', aufgabe: 'MatrNr der Studenten, die an Vorlesungen teilnehmen (Relation hoeren).', tipp: 'Projektion auf hoeren – wie viele Tupel bleiben ohne Duplikate?', loesung: 'π MatrNr (hören)\nSELECT DISTINCT MatrNr FROM hoeren;\n→ 6 MatrNr: 25403, 26120, 27550, 28106, 29120, 29555 (ohne DISTINCT 13 Tupel)', db: 'uni', sql: 'SELECT DISTINCT MatrNr FROM hoeren' },
      { nr: '2.8', aufgabe: 'PersNr der Professoren, die Vorlesungen halten (Relation Vorlesungen).', tipp: 'Das Attribut heißt dort nicht PersNr.', loesung: 'ρ PersNr←gelesenVon (π gelesenVon (Vorlesungen))\nSELECT DISTINCT gelesenVon AS PersNr FROM Vorlesungen;\n→ 2125, 2126, 2133, 2134, 2137', db: 'uni', sql: 'SELECT DISTINCT gelesenVon AS PersNr FROM Vorlesungen' },
      { nr: '2.9', aufgabe: 'Namen aller Studenten und Assistenten.', tipp: 'Mengenoperator – Schemagleichheit herstellen.', loesung: 'π Name (Studenten) ∪ π Name (Assistenten)\nSELECT Name FROM Studenten UNION SELECT Name FROM Assistenten;\n→ 14 Namen (8 + 6, keine Überschneidung)', db: 'uni', sql: 'SELECT Name FROM Studenten UNION SELECT Name FROM Assistenten' },
      { nr: '2.10', aufgabe: 'Alle Räume, in denen Professoren residieren.', tipp: 'Projektion auf ein Attribut.', loesung: 'π Raum (Professoren)\nSELECT DISTINCT Raum FROM Professoren;\n→ 226, 232, 310, 52, 309, 36, 7', db: 'uni', sql: 'SELECT DISTINCT Raum FROM Professoren' },
    ] },
  { id: 'p3', nr: '#3', titel: 'Eigene Beispiele für alle 15 Operatoren', abgabe: '28.10.2026', intro: 'Für jeden Operator: verbal, RelaX, SQL. Die Lösungen sind Beispiele – eigene Beispiele sind genauso richtig, solange der Operator korrekt eingesetzt wird.',
    aufgaben: [
      { nr: '3.1 σ', aufgabe: 'Selektion', tipp: 'Bedingung auf Tupel einer Relation.', loesung: "Verbal: C3-Professoren\nRelaX: σ Rang = 'C3' (Professoren)\nSQL: SELECT * FROM Professoren WHERE Rang = 'C3';\n→ Kopernikus, Popper, Augustinus", db: 'uni', sql: "SELECT * FROM Professoren WHERE Rang = 'C3'" },
      { nr: '3.2 π', aufgabe: 'Projektion', tipp: 'Attribute auswählen; Duplikate verschwinden.', loesung: 'Verbal: Alle vorkommenden SWS-Werte\nRelaX: π SWS (Vorlesungen)\nSQL: SELECT DISTINCT SWS FROM Vorlesungen;\n→ 4, 3, 2', db: 'uni', sql: 'SELECT DISTINCT SWS FROM Vorlesungen' },
      { nr: '3.3 ρ', aufgabe: 'Umbenennung', tipp: 'Relation oder Attribut umbenennen.', loesung: 'Verbal: Assistenten mit Attribut Chef statt Boss\nRelaX: ρ Chef←Boss (Assistenten)\nSQL: SELECT PersNr, Name, Fachgebiet, Boss AS Chef FROM Assistenten;', db: 'uni', sql: 'SELECT PersNr, Name, Fachgebiet, Boss AS Chef FROM Assistenten' },
      { nr: '3.4 ×', aufgabe: 'Kreuzprodukt', tipp: 'Jedes Tupel mit jedem – Anzahl = Produkt der Tupelanzahlen.', loesung: 'Verbal: Alle Kombinationen aus C3-Professoren und Assistenten\nRelaX: σ Rang=\'C3\'(Professoren) ⨯ Assistenten\nSQL: SELECT * FROM Professoren CROSS JOIN Assistenten WHERE Rang = \'C3\';\n→ 3 · 6 = 18 Tupel', db: 'uni', sql: "SELECT * FROM Professoren CROSS JOIN Assistenten WHERE Rang = 'C3'" },
      { nr: '3.5 −', aufgabe: 'Mengendifferenz', tipp: 'Schemagleichheit! Typisch: „… die KEINE …“.', loesung: 'Verbal: MatrNr der Studenten, die keine Vorlesung hören\nRelaX: π MatrNr (Studenten) − π MatrNr (hoeren)\nSQL: SELECT MatrNr FROM Studenten EXCEPT SELECT MatrNr FROM hoeren;\n→ 24002, 26830\nOracle 19c: MINUS statt EXCEPT', db: 'uni', sql: 'SELECT MatrNr FROM Studenten EXCEPT SELECT MatrNr FROM hoeren' },
      { nr: '3.6 ∪', aufgabe: 'Vereinigung', tipp: 'Schemagleichheit mit π und ρ.', loesung: 'Verbal: PersNr aller Professoren und Assistenten\nRelaX: π PersNr (Professoren) ∪ π PersNr (Assistenten)\nSQL: SELECT PersNr FROM Professoren UNION SELECT PersNr FROM Assistenten;\n→ 13 PersNr', db: 'uni', sql: 'SELECT PersNr FROM Professoren UNION SELECT PersNr FROM Assistenten' },
      { nr: '3.7 ∩', aufgabe: 'Mengendurchschnitt', tipp: 'Beispiel der VL: C4-Professoren, die mindestens eine Vorlesung halten.', loesung: "Verbal: PersNr der C4-Professoren, die lesen\nRelaX: π PersNr (ρ PersNr←gelesenVon (Vorlesungen)) ∩ π PersNr (σ Rang='C4' (Professoren))\nSQL: SELECT gelesenVon FROM Vorlesungen INTERSECT SELECT PersNr FROM Professoren WHERE Rang = 'C4';\n→ 2125, 2126, 2137", db: 'uni', sql: "SELECT gelesenVon FROM Vorlesungen INTERSECT SELECT PersNr FROM Professoren WHERE Rang = 'C4'" },
      { nr: '3.8 ⋈', aufgabe: 'Natürlicher Verbund', tipp: 'Verbindet über gleichnamige Attribute.', loesung: 'Verbal: Studenten mit ihren Prüfungen\nRelaX: Studenten ⨝ pruefen\nSQL: SELECT * FROM Studenten NATURAL JOIN pruefen;\n→ 3 Tupel (Carnap, Jonas, Schopenhauer)', db: 'uni', sql: 'SELECT * FROM Studenten NATURAL JOIN pruefen' },
      { nr: '3.9 ⋈θ', aufgabe: 'Theta-Join', tipp: 'Join mit beliebiger Bedingung über verschieden benannte Attribute.', loesung: 'Verbal: Professoren mit ihren Assistenten\nRelaX: Professoren ⨝ Professoren.PersNr = Assistenten.Boss Assistenten\nSQL: SELECT * FROM Professoren p JOIN Assistenten a ON p.PersNr = a.Boss;\n→ 6 Tupel', db: 'uni', sql: 'SELECT * FROM Professoren p JOIN Assistenten a ON p.PersNr = a.Boss' },
      { nr: '3.10 ⋊', aufgabe: 'Rechter Semi-Join', tipp: 'Ergebnis hat nur die Attribute der RECHTEN Relation.', loesung: 'Verbal: Vorlesungen, die mindestens einen Hörer haben\nRelaX: hoeren ⋊ Vorlesungen\nSQL: SELECT * FROM Vorlesungen v WHERE EXISTS (SELECT * FROM hoeren h WHERE h.VorlNr = v.VorlNr);\n→ 8 Vorlesungen (ohne Erkenntnistheorie, Die 3 Kritiken)', db: 'uni', sql: 'SELECT * FROM Vorlesungen v WHERE EXISTS (SELECT * FROM hoeren h WHERE h.VorlNr = v.VorlNr)' },
      { nr: '3.11 ⋉', aufgabe: 'Linker Semi-Join', tipp: 'Ergebnis hat nur die Attribute der LINKEN Relation.', loesung: 'Verbal: Studenten, die mindestens eine Vorlesung hören\nRelaX: Studenten ⋉ hoeren\nSQL: SELECT * FROM Studenten s WHERE EXISTS (SELECT * FROM hoeren h WHERE h.MatrNr = s.MatrNr);\n→ 6 Studenten', db: 'uni', sql: 'SELECT * FROM Studenten s WHERE EXISTS (SELECT * FROM hoeren h WHERE h.MatrNr = s.MatrNr)' },
      { nr: '3.12 ⟕', aufgabe: 'Linker äußerer Join', tipp: 'Alle Tupel links, fehlende Partner = NULL.', loesung: 'Verbal: Alle Studenten mit ihren Prüfungen (auch ohne Prüfung)\nRelaX: Studenten ⟕ pruefen\nSQL: SELECT * FROM Studenten s LEFT OUTER JOIN pruefen p ON s.MatrNr = p.MatrNr;\n→ 8 Tupel, 5 davon mit NULL bei Note', db: 'uni', sql: 'SELECT * FROM Studenten s LEFT OUTER JOIN pruefen p ON s.MatrNr = p.MatrNr' },
      { nr: '3.13 ⟖', aufgabe: 'Rechter äußerer Join', tipp: 'Alle Tupel rechts.', loesung: 'Verbal: Alle Vorlesungen mit ihren Hörern (auch ohne Hörer)\nRelaX: hoeren ⟖ Vorlesungen\nSQL: SELECT * FROM hoeren h RIGHT OUTER JOIN Vorlesungen v ON h.VorlNr = v.VorlNr;\n→ 15 Tupel (13 + 2 Vorlesungen ohne Hörer)', db: 'uni', sql: 'SELECT * FROM hoeren h RIGHT OUTER JOIN Vorlesungen v ON h.VorlNr = v.VorlNr' },
      { nr: '3.14 ⟗', aufgabe: 'Voller äußerer Join', tipp: 'Beispiel der VL: Vorlesungen und Assistenten über gelesenVon = Boss.', loesung: 'Verbal: Vorlesungen und Assistenten desselben Professors, inkl. aller ohne Partner\nRelaX: Vorlesungen ⟗ Vorlesungen.gelesenVon = Assistenten.Boss Assistenten\nSQL: SELECT * FROM Vorlesungen v FULL OUTER JOIN Assistenten a ON v.gelesenVon = a.Boss;\n→ 18 Tupel: 12 Paare (Sokrates, Russel: je 3 Vorlesungen × 2 Assistenten) + 4 Vorlesungen ohne Assistent (Kant ×2, Popper, Augustinus) + 2 Assistenten ohne Vorlesung (Rhetikus, Newton – Kopernikus liest nicht)', db: 'uni', sql: 'SELECT * FROM Vorlesungen v FULL OUTER JOIN Assistenten a ON v.gelesenVon = a.Boss' },
      { nr: '3.15 ÷', aufgabe: 'Relationale Division', tipp: '„alle“-Frage; Divisor = die Menge, die vollständig abgedeckt sein muss.', loesung: "Verbal: MatrNr der Studenten, die Grundzüge UND Glaube und Wissen hören\nRelaX: hoeren ÷ π VorlNr (σ Titel='Grundzüge' ∨ Titel='Glaube und Wissen' (Vorlesungen))\nSQL (doppeltes NOT EXISTS): SELECT DISTINCT h.MatrNr FROM hoeren h WHERE NOT EXISTS (SELECT * FROM Vorlesungen v WHERE v.Titel IN ('Grundzüge','Glaube und Wissen') AND NOT EXISTS (SELECT * FROM hoeren h2 WHERE h2.VorlNr = v.VorlNr AND h2.MatrNr = h.MatrNr));\n→ 29555 (Feuerbach)", db: 'uni', sql: "SELECT DISTINCT h.MatrNr FROM hoeren h WHERE NOT EXISTS (SELECT * FROM Vorlesungen v WHERE v.Titel IN ('Grundzüge','Glaube und Wissen') AND NOT EXISTS (SELECT * FROM hoeren h2 WHERE h2.VorlNr = v.VorlNr AND h2.MatrNr = h.MatrNr))" },
    ] },
  { id: 'p4', nr: '#4', titel: 'SPJ-Datenbank (Lieferanten, Teile, Projekte)', abgabe: '11.11.2026', intro: 'SPJ-DB per DDL/DML/DCL anlegen, RelaX-Datensatz erstellen, Aufgaben 18, 30, 31, 32, 37 lösen (Quelle: Prof. Schwenkert). In der Konsole: Datenbank „SPJ“.',
    aufgaben: [
      { nr: 'DDL/DCL', aufgabe: 'Lege S, P, J und SPJ mit Schlüsseln an, fülle sie und gib Leserechte an DBMI60.', tipp: 'SPJ hat einen zusammengesetzten Primärschlüssel aus drei Fremdschlüsseln. Erst S, P, J füllen, dann SPJ.', loesung: "CREATE TABLE S (SNO CHAR(3) PRIMARY KEY, SNAME VARCHAR(20), STATUS INTEGER, CITY VARCHAR(20));\nCREATE TABLE P (PNO CHAR(3) PRIMARY KEY, PNAME VARCHAR(20), COLOR VARCHAR(10), WEIGHT INTEGER, CITY VARCHAR(20));\nCREATE TABLE J (JNO CHAR(3) PRIMARY KEY, JNAME VARCHAR(20), CITY VARCHAR(20));\nCREATE TABLE SPJ (SNO CHAR(3) REFERENCES S, PNO CHAR(3) REFERENCES P, JNO CHAR(3) REFERENCES J, QTY INTEGER, PRIMARY KEY (SNO, PNO, JNO));\nINSERT INTO S VALUES ('S1','Smith',20,'London'); … (alle Tupel aus der Abbildung)\nGRANT SELECT ON S TO DBMI60; (ebenso P, J, SPJ)" },
      { nr: '18a', aufgabe: 'Algebra: Nummern der Lieferanten, die keine Teile liefern.', tipp: 'Alle Lieferanten minus die, die in SPJ vorkommen.', loesung: 'π SNO (S) − π SNO (SPJ)\n→ leere Menge: S1–S5 liefern alle', db: 'spj', sql: 'SELECT SNO FROM S EXCEPT SELECT SNO FROM SPJ' },
      { nr: '18b', aufgabe: 'Algebra: Lieferanten, die P1 oder P2 liefern.', tipp: 'Selektion mit ∨, dann Projektion.', loesung: "π SNO (σ PNO='P1' ∨ PNO='P2' (SPJ))\n→ S1, S5", db: 'spj', sql: "SELECT DISTINCT SNO FROM SPJ WHERE PNO = 'P1' OR PNO = 'P2'" },
      { nr: '18c', aufgabe: 'Algebra: Projektnummern der Projekte, die keinen Lieferanten (aktiv oder passiv) am Ort haben.', tipp: '„aktiv oder passiv“: Es zählt jeder Lieferant in der Stadt, egal ob er an das Projekt liefert. Join über CITY.', loesung: 'π JNO (J) − π JNO (J ⋈ J.CITY=S.CITY S)\n→ J2 (Rome), J6 (Oslo) – Lieferanten sitzen nur in London, Paris, Athens', db: 'spj', sql: 'SELECT JNO FROM J EXCEPT SELECT J.JNO FROM J JOIN S ON J.CITY = S.CITY' },
      { nr: '18d', aufgabe: 'Algebra: Lieferantennamen der Lieferanten, die J1 beliefern.', tipp: 'Selektion auf SPJ, dann natürlicher Join mit S.', loesung: "π SNAME (S ⋈ σ JNO='J1' (SPJ))\n→ Smith, Jones, Blake", db: 'spj', sql: "SELECT DISTINCT S.SNAME FROM S JOIN SPJ ON S.SNO = SPJ.SNO WHERE SPJ.JNO = 'J1'" },
      { nr: '18e', aufgabe: 'Algebra: Projekte am gleichen Ort wie J5.', tipp: 'J mit einer umbenannten Kopie von J verbinden (Self Join).', loesung: "π J.JNO (J ⋈ J.CITY=J2.CITY (σ JNO='J5' (ρ J2 (J))))\n→ J5, J7 (London). Ohne J5 selbst: zusätzlich σ J.JNO ≠ 'J5' → J7", db: 'spj', sql: "SELECT j.JNO FROM J j JOIN J j2 ON j.CITY = j2.CITY WHERE j2.JNO = 'J5'" },
      { nr: '18f', aufgabe: 'Algebra: Lieferanten, die mindestens P1 und P6 liefern.', tipp: 'Zwei Mengen schneiden – oder dividieren.', loesung: "π SNO (σ PNO='P1' (SPJ)) ∩ π SNO (σ PNO='P6' (SPJ))\noder: π SNO,PNO (SPJ) ÷ {(P1), (P6)}\n→ S5", db: 'spj', sql: "SELECT SNO FROM SPJ WHERE PNO = 'P1' INTERSECT SELECT SNO FROM SPJ WHERE PNO = 'P6'" },
      { nr: '30a', aufgabe: 'Verbal + Ergebnis: SELECT COUNT(DISTINCT PNO) FROM SPJ;', tipp: 'DISTINCT innerhalb von COUNT.', loesung: 'Anzahl der verschiedenen gelieferten Teile → 6', db: 'spj', sql: 'SELECT COUNT(DISTINCT PNO) FROM SPJ' },
      { nr: '30b', aufgabe: 'Verbal + Ergebnis: SELECT SUM(QTY)/COUNT(DISTINCT PNO) FROM SPJ;', tipp: 'Gesamtmenge geteilt durch Anzahl Teile.', loesung: 'Durchschnittliche Gesamtliefermenge pro gelieferter Teileart: 8.500 / 6 ≈ 1.416,7 (Oracle). Die Konsole (SQLite) rechnet mit Ganzzahlen ganzzahlig → 1416.', db: 'spj', sql: 'SELECT SUM(QTY)/COUNT(DISTINCT PNO) FROM SPJ' },
      { nr: '30c', aufgabe: 'Verbal + Ergebnis: SELECT PNO, SUM(QTY), SUM(QTY)/COUNT(DISTINCT PNO) FROM SPJ GROUP BY PNO;', tipp: 'Wie viele verschiedene PNO gibt es INNERHALB einer Gruppe?', loesung: 'Pro Teil die Gesamtliefermenge – zweimal. In jeder Gruppe ist COUNT(DISTINCT PNO) = 1, also ist das dritte Attribut gleich dem zweiten.\nP1 1.000 · P2 300 · P3 3.500 · P4 1.300 · P5 1.100 · P6 1.300', db: 'spj', sql: 'SELECT PNO, SUM(QTY), SUM(QTY)/COUNT(DISTINCT PNO) FROM SPJ GROUP BY PNO' },
      { nr: '30d', aufgabe: 'Verbal + Ergebnis: … GROUP BY PNO HAVING SUM(QTY) > (SUM(QTY)/COUNT(DISTINCT PNO));', tipp: 'Siehe 30c – was steht rechts vom > in jeder Gruppe?', loesung: 'Teile, deren Gesamtmenge größer ist als … ihre eigene Gesamtmenge (da COUNT(DISTINCT PNO) = 1 je Gruppe). x > x ist nie wahr → leere Menge.\nVermutlich gemeint: größer als der Durchschnitt über ALLE Teile → das braucht eine Unterabfrage (siehe 31e).', db: 'spj', sql: 'SELECT PNO, SUM(QTY) FROM SPJ GROUP BY PNO HAVING SUM(QTY) > (SUM(QTY)/COUNT(DISTINCT PNO))' },
      { nr: '30e', aufgabe: 'Verbal + Ergebnis: SELECT PNO, MAX(QTY) FROM SPJ;', tipp: 'GROUP-BY-Regel.', loesung: 'Ungültig: PNO ist weder aggregiert noch im GROUP BY → Oracle meldet ORA-00937 („keine Gruppenfunktion für Einzelgruppe“).\nAchtung: SQLite in der Konsole akzeptiert das fälschlich und zeigt irgendein PNO – in Oracle und im Standard ein Fehler.\nGemeint war vermutlich: SELECT PNO, MAX(QTY) FROM SPJ GROUP BY PNO;' },
      { nr: '31a', aufgabe: 'SQL: Für jedes gelieferte Teil: Teilenummer, Gesamtliefermenge und durchschnittliche Liefermenge.', tipp: 'Gruppieren nach PNO, zwei Aggregate.', loesung: 'SELECT PNO, SUM(QTY) AS Gesamt, AVG(QTY) AS Durchschnitt FROM SPJ GROUP BY PNO;\n→ P1 1000/333,3 · P2 300/150 · P3 3500/388,9 · P4 1300/650 · P5 1100/275 · P6 1300/325', db: 'spj', sql: 'SELECT PNO, SUM(QTY) AS Gesamt, AVG(QTY) AS Durchschnitt FROM SPJ GROUP BY PNO' },
      { nr: '31b', aufgabe: 'SQL: Für jedes von S1 gelieferte Teil: Teilenummer, minimale und maximale Liefermenge.', tipp: 'Erst mit WHERE auf S1 filtern, dann gruppieren.', loesung: "SELECT PNO, MIN(QTY), MAX(QTY) FROM SPJ WHERE SNO = 'S1' GROUP BY PNO;\n→ P1 200 700", db: 'spj', sql: "SELECT PNO, MIN(QTY), MAX(QTY) FROM SPJ WHERE SNO = 'S1' GROUP BY PNO" },
      { nr: '31c', aufgabe: 'SQL: Teilenummer und Gesamtliefermenge jedes Teils mit Gesamtliefermenge > 1000.', tipp: 'Bedingung auf ein Aggregat → nicht WHERE.', loesung: 'SELECT PNO, SUM(QTY) FROM SPJ GROUP BY PNO HAVING SUM(QTY) > 1000;\n→ P3 3500 · P4 1300 · P5 1100 · P6 1300 (P1 hat genau 1000 → nicht > 1000)', db: 'spj', sql: 'SELECT PNO, SUM(QTY) FROM SPJ GROUP BY PNO HAVING SUM(QTY) > 1000' },
      { nr: '31d', aufgabe: 'SQL: Für jedes Teil pro Lieferant die Gesamtliefermenge.', tipp: 'Gruppieren nach zwei Attributen.', loesung: 'SELECT SNO, PNO, SUM(QTY) FROM SPJ GROUP BY SNO, PNO ORDER BY SNO, PNO;\n→ 12 Gruppen, z. B. S1/P1 900, S2/P3 3100, S5/P5 1000', db: 'spj', sql: 'SELECT SNO, PNO, SUM(QTY) FROM SPJ GROUP BY SNO, PNO' },
      { nr: '31e', aufgabe: 'SQL: Teilenummer und Gesamtliefermenge jedes Teils, dessen Gesamtliefermenge größer als die durchschnittliche Gesamtliefermenge aller gelieferten Teile ist.', tipp: 'Der Vergleichswert muss über ALLE Teile berechnet werden → unkorrelierte Unterabfrage im HAVING.', loesung: 'SELECT PNO, SUM(QTY) FROM SPJ GROUP BY PNO\nHAVING SUM(QTY) > (SELECT SUM(QTY)/COUNT(DISTINCT PNO) FROM SPJ);\nDurchschnitt ≈ 1.416,7 → P3 3500', db: 'spj', sql: 'SELECT PNO, SUM(QTY) FROM SPJ GROUP BY PNO HAVING SUM(QTY) > (SELECT SUM(QTY)/COUNT(DISTINCT PNO) FROM SPJ)' },
      { nr: '32', aufgabe: 'Füge den Lieferanten „Stewart“ mit Nummer S6 hinzu; Status und Stadt sind unbekannt.', tipp: 'Unbekannt = NULL. Nur die bekannten Attribute angeben.', loesung: "INSERT INTO S (SNO, SNAME) VALUES ('S6', 'Stewart');\n(gleichwertig: INSERT INTO S VALUES ('S6','Stewart',NULL,NULL);)\nKonsole: Führe diesen INSERT zuerst aus, dann 32a–f." },
      { nr: '32a', aufgabe: 'Alle Lieferanten, deren Stadt unbekannt ist.', tipp: 'Nicht mit = vergleichen.', loesung: 'SELECT * FROM S WHERE CITY IS NULL;\n→ S6 Stewart', db: 'spj', pre: "INSERT INTO S (SNO, SNAME) VALUES ('S6','Stewart');", sql: 'SELECT * FROM S WHERE CITY IS NULL' },
      { nr: '32b', aufgabe: 'Wie viele Lieferanten sind mit Sicherheit nicht in London?', tipp: 'Was ergibt CITY <> \'London\' für S6?', loesung: "SELECT COUNT(*) FROM S WHERE CITY <> 'London';\n→ 3 (S2, S3, S5). Für S6 ergibt der Vergleich NULL → nicht „mit Sicherheit“, wird nicht gezählt.", db: 'spj', pre: "INSERT INTO S (SNO, SNAME) VALUES ('S6','Stewart');", sql: "SELECT COUNT(*) FROM S WHERE CITY <> 'London'" },
      { nr: '32c', aufgabe: 'Begründe: SELECT COUNT(CITY) / COUNT(*) / COUNT(SNAME) FROM S WHERE CITY IS NULL;', tipp: 'Was zählt COUNT(Attribut) im Unterschied zu COUNT(*)?', loesung: 'COUNT(CITY) = 0 – COUNT(Attribut) ignoriert NULL, und im einzigen Tupel ist CITY NULL.\nCOUNT(*) = 1 – zählt Tupel.\nCOUNT(SNAME) = 1 – SNAME = Stewart ist nicht NULL.', db: 'spj', pre: "INSERT INTO S (SNO, SNAME) VALUES ('S6','Stewart');", sql: 'SELECT COUNT(CITY), COUNT(*), COUNT(SNAME) FROM S WHERE CITY IS NULL' },
      { nr: '32d-i', aufgabe: "Ergebnis + Begründung: SELECT SNO FROM S WHERE CITY IN (SELECT CITY FROM J WHERE JNO='J8');", tipp: 'Gibt es J8?', loesung: 'Leere Menge: J8 existiert nicht → Unterabfrage leer → IN (leere Menge) ist für kein Tupel wahr.', db: 'spj', pre: "INSERT INTO S (SNO, SNAME) VALUES ('S6','Stewart');", sql: "SELECT SNO FROM S WHERE CITY IN (SELECT CITY FROM J WHERE JNO='J8')" },
      { nr: '32d-ii', aufgabe: 'Ergebnis + Begründung: SELECT JNAME FROM J WHERE CITY NOT IN (SELECT CITY FROM S);', tipp: 'Die Unterabfrage enthält jetzt einen NULL-Wert (S6). Was ergibt „Rome <> NULL“?', loesung: "Leere Menge! Die Unterabfrage liefert {London, Paris, Athens, NULL}. NOT IN = CITY <> London AND … AND CITY <> NULL. Der letzte Vergleich ist NULL → das Ganze höchstens NULL → kein Tupel.\nVor dem INSERT von S6 wären Punch (Rome) und Terminal (Oslo) gekommen.", db: 'spj', pre: "INSERT INTO S (SNO, SNAME) VALUES ('S6','Stewart');", sql: 'SELECT JNAME FROM J WHERE CITY NOT IN (SELECT CITY FROM S)' },
      { nr: '32e', aufgabe: 'Ermittle alle Projekte, die keinen Lieferanten in ihrer Stadt haben.', tipp: 'Wie formulierst du das NULL-sicher (siehe 32d-ii)?', loesung: 'SELECT * FROM J WHERE NOT EXISTS (SELECT * FROM S WHERE S.CITY = J.CITY);\n→ J2 Punch (Rome), J6 Terminal (Oslo) – NOT EXISTS ist NULL-sicher.', db: 'spj', pre: "INSERT INTO S (SNO, SNAME) VALUES ('S6','Stewart');", sql: 'SELECT * FROM J WHERE NOT EXISTS (SELECT * FROM S WHERE S.CITY = J.CITY)' },
      { nr: '32f', aufgabe: 'Wird DELETE FROM S WHERE CITY = NULL akzeptiert? Lösche S6, ohne SNO und SNAME zu benutzen.', tipp: 'Syntaktisch korrekt ≠ sinnvoll.', loesung: 'Ja, der Befehl wird akzeptiert (syntaktisch korrekt), löscht aber 0 Tupel: CITY = NULL ist nie TRUE.\nRichtig: DELETE FROM S WHERE CITY IS NULL;  (optional zusätzlich AND STATUS IS NULL)' },
      { nr: '37a', aufgabe: 'Erhöhe den Status um 5 bei allen Lieferanten mit mehr als 3 Lieferungen.', tipp: 'Lieferungen pro Lieferant zählen → Unterabfrage mit GROUP BY/HAVING im WHERE des UPDATE.', loesung: 'UPDATE S SET STATUS = STATUS + 5\nWHERE SNO IN (SELECT SNO FROM SPJ GROUP BY SNO HAVING COUNT(*) > 3);\nLieferungen: S1 2, S2 8, S3 2, S4 2, S5 10 → S2: 10 → 15, S5: 30 → 35', db: 'spj', pre: 'UPDATE S SET STATUS = STATUS + 5 WHERE SNO IN (SELECT SNO FROM SPJ GROUP BY SNO HAVING COUNT(*) > 3);', sql: 'SELECT SNO, STATUS FROM S' },
      { nr: '37b', aufgabe: 'Setze den Status aller Lieferanten aus London auf Mᵢ/10, wobei Mᵢ die maximale Einzelliefermenge von Sᵢ ist.', tipp: 'Korrelierte Unterabfrage im SET.', loesung: "UPDATE S SET STATUS = (SELECT MAX(QTY)/10 FROM SPJ WHERE SPJ.SNO = S.SNO)\nWHERE CITY = 'London';\nS1: max 700 → 70 · S4: max 300 → 30", db: 'spj', pre: "UPDATE S SET STATUS = (SELECT MAX(QTY)/10 FROM SPJ WHERE SPJ.SNO = S.SNO) WHERE CITY = 'London';", sql: 'SELECT SNO, STATUS FROM S' },
      { nr: '37c', aufgabe: 'Lege die Änderungsrelation CHG (OLD, NEW) mit (S1, N1), (S4, N4) an und aktualisiere damit S.', tipp: 'Korrelierte Unterabfrage im SET; nur Tupel ändern, die in CHG vorkommen. Was sagt der Fremdschlüssel in SPJ dazu?', loesung: "CREATE TABLE CHG (OLD CHAR(3), NEW CHAR(3));\nINSERT INTO CHG VALUES ('S1','N1');\nINSERT INTO CHG VALUES ('S4','N4');\nUPDATE S SET SNO = (SELECT NEW FROM CHG WHERE CHG.OLD = S.SNO)\nWHERE SNO IN (SELECT OLD FROM CHG);\nAchtung: Mit Fremdschlüssel SPJ.SNO → S weist Oracle das UPDATE zurück (S1, S4 werden referenziert; Oracle kennt kein ON UPDATE CASCADE). Dann erst SPJ ändern oder den Constraint vorübergehend deaktivieren.\nOLD/NEW als Attributnamen sind ungünstig (Trigger-Bezeichner); besser AltNr/NeuNr.", db: 'spj', pre: "CREATE TABLE CHG (OLD CHAR(3), NEW CHAR(3)); INSERT INTO CHG VALUES ('S1','N1'); INSERT INTO CHG VALUES ('S4','N4'); UPDATE S SET SNO = (SELECT NEW FROM CHG WHERE CHG.OLD = S.SNO) WHERE SNO IN (SELECT OLD FROM CHG);", sql: 'SELECT * FROM S' },
    ] },
  { id: 'p5', nr: '#5', titel: 'Familienbaum', abgabe: '18.11.2026', intro: 'Familienbaum als Relationen modellieren und abfragen. Die Konsole nutzt Person(Name, Geschlecht, Geburtsjahr, Sterbejahr) und Elternteil(Kind, Elternteil) – ein mögliches Modell.',
    aufgaben: [
      { nr: 'Modell', aufgabe: 'Implementiere den Familienbaum als Relation(en) und fülle sie per SQL.', tipp: 'Eine Person hat höchstens zwei Eltern – aber Eltern beliebig viele Kinder. Beziehung Kind–Elternteil als eigene Relation ist am flexibelsten.', loesung: "CREATE TABLE Person (Name VARCHAR(20) PRIMARY KEY, Geschlecht CHAR(1) CHECK (Geschlecht IN ('M','F')), Geburtsjahr INTEGER NOT NULL, Sterbejahr INTEGER);\nCREATE TABLE Elternteil (Kind VARCHAR(20) REFERENCES Person(Name), Elternteil VARCHAR(20) REFERENCES Person(Name), PRIMARY KEY (Kind, Elternteil));\nINSERT INTO Person VALUES ('Albert','M',1917,1966); … (20 Personen)\nINSERT INTO Elternteil VALUES ('Hans','Albert'); … (26 Tupel)\nAlternative: Person mit Attributen Vater und Mutter (Fremdschlüssel auf Person). Name als Schlüssel ist nur hier vertretbar (alle Namen eindeutig)." },
      { nr: '5.1', aufgabe: 'Finde alle Nichten von Markus.', tipp: 'Nichte = Tochter eines Geschwisters. Geschwister = andere Person mit gemeinsamem Elternteil. Achtung: Andrea ist männlich.', loesung: "SELECT DISTINCT k.Name\nFROM Elternteil em\nJOIN Elternteil eg ON eg.Elternteil = em.Elternteil AND eg.Kind <> em.Kind\nJOIN Elternteil ek ON ek.Elternteil = eg.Kind\nJOIN Person k ON k.Name = ek.Kind\nWHERE em.Kind = 'Markus' AND k.Geschlecht = 'F';\n→ Sonja (Tochter von Schwester Silke). Andrea ist laut Baum (M).", db: 'fam', sql: "SELECT DISTINCT k.Name FROM Elternteil em JOIN Elternteil eg ON eg.Elternteil = em.Elternteil AND eg.Kind <> em.Kind JOIN Elternteil ek ON ek.Elternteil = eg.Kind JOIN Person k ON k.Name = ek.Kind WHERE em.Kind = 'Markus' AND k.Geschlecht = 'F'" },
      { nr: '5.2', aufgabe: 'Was müsste man zusätzlich modellieren, um den Schwager von Markus zu bestimmen?', tipp: 'Schwager = Bruder des Ehepartners oder Ehemann der Schwester. Welche Beziehung fehlt im Modell?', loesung: 'Die Ehe bzw. Partnerschaft, z. B. Relation Ehe(Partner1, Partner2). Aus gemeinsamen Kindern kann man sie nur raten – kinderlose Paare fehlen, gemeinsame Kinder bedeuten nicht zwingend Ehe.\nMit Ehe: Schwager von Markus = Thomas (Ehemann der Schwester Silke); Brüder von Ute gibt es im Baum nicht.' },
      { nr: '5.3', aufgabe: 'Welches Familienmitglied hat am längsten gelebt?', tipp: 'Lebensdauer = Sterbejahr − Geburtsjahr. Klären: nur Verstorbene, oder Lebende mit aktuellem Jahr?', loesung: 'Nur Verstorbene:\nSELECT Name, Sterbejahr - Geburtsjahr AS Lebensdauer FROM Person\nWHERE Sterbejahr - Geburtsjahr = (SELECT MAX(Sterbejahr - Geburtsjahr) FROM Person);\n→ Anna (80 Jahre). NULL bei Lebenden fällt automatisch heraus.\nMit Lebenden (Standard: COALESCE(Sterbejahr, EXTRACT(YEAR FROM CURRENT_DATE)) - Geburtsjahr): 2026 → Dagmar 81 (1945), vor Anna und Maria (je 80).', db: 'fam', sql: 'SELECT Name, Sterbejahr - Geburtsjahr AS Lebensdauer FROM Person WHERE Sterbejahr - Geburtsjahr = (SELECT MAX(Sterbejahr - Geburtsjahr) FROM Person)' },
      { nr: '5.4', aufgabe: 'Wie viele Frauen und wie viele Männer gibt es in der Familie?', tipp: 'Gruppieren nach Geschlecht.', loesung: 'SELECT Geschlecht, COUNT(*) AS Anzahl FROM Person GROUP BY Geschlecht;\n→ F 8 · M 12', db: 'fam', sql: 'SELECT Geschlecht, COUNT(*) AS Anzahl FROM Person GROUP BY Geschlecht' },
      { nr: '5.5', aufgabe: 'Statistik: Wie viele Kinder wurden in den 70er, 80er und 90er Jahren geboren?', tipp: 'Jahrzehnt per CASE bilden und danach gruppieren. „Kinder“ = Personen mit Eltern im Baum – oder alle Geburten?', loesung: "SELECT Jahrzehnt, COUNT(*) AS Anzahl\nFROM (SELECT CASE WHEN Geburtsjahr BETWEEN 1970 AND 1979 THEN '70er'\n                  WHEN Geburtsjahr BETWEEN 1980 AND 1989 THEN '80er'\n                  WHEN Geburtsjahr BETWEEN 1990 AND 1999 THEN '90er' END AS Jahrzehnt\n      FROM Person WHERE Name IN (SELECT Kind FROM Elternteil)) t\nWHERE Jahrzehnt IS NOT NULL GROUP BY Jahrzehnt;\n→ Kinder mit Eltern im Baum: 70er 1 (Anke) · 80er 1 (Sonja) · 90er 3 (Andrea, Sven, Olaf)\nAlle Geburten: 70er 3 (+ Ute, Till) · 80er 1 · 90er 3\nOracle: Attribut-Alias nicht im GROUP BY derselben Ebene nutzbar → Unterabfrage wie oben.", db: 'fam', sql: "SELECT Jahrzehnt, COUNT(*) AS Anzahl FROM (SELECT CASE WHEN Geburtsjahr BETWEEN 1970 AND 1979 THEN '70er' WHEN Geburtsjahr BETWEEN 1980 AND 1989 THEN '80er' WHEN Geburtsjahr BETWEEN 1990 AND 1999 THEN '90er' END AS Jahrzehnt FROM Person WHERE Name IN (SELECT Kind FROM Elternteil)) t WHERE Jahrzehnt IS NOT NULL GROUP BY Jahrzehnt" },
      { nr: '5.6', aufgabe: 'Finde alle Enkelkinder von Maria.', tipp: 'Zwei Stufen: Kinder von Maria, dann deren Kinder (Self Join auf Elternteil).', loesung: "SELECT e2.Kind FROM Elternteil e1 JOIN Elternteil e2 ON e2.Elternteil = e1.Kind\nWHERE e1.Elternteil = 'Maria';\n→ Sven, Olaf (über Markus), Sonja, Andrea (über Silke)", db: 'fam', sql: "SELECT e2.Kind FROM Elternteil e1 JOIN Elternteil e2 ON e2.Elternteil = e1.Kind WHERE e1.Elternteil = 'Maria'" },
      { nr: '5.7', aufgabe: 'Finde alle Nachkommen von Opa Albert, geordnet nach Alter (Jahrgang).', tipp: 'Beliebig viele Stufen → transitive Hülle (rekursive Anfrage). Ältester zuerst.', loesung: "WITH RECURSIVE Nachkommen(Name) AS (\n  SELECT Kind FROM Elternteil WHERE Elternteil = 'Albert'\n  UNION\n  SELECT e.Kind FROM Elternteil e JOIN Nachkommen n ON e.Elternteil = n.Name)\nSELECT p.Name, p.Geburtsjahr FROM Nachkommen n JOIN Person p ON p.Name = n.Name\nORDER BY p.Geburtsjahr;\n→ 13: Hans 1940, Dagmar 1945, Rudolf 1950, Markus 1965, Silke 1968, Anke 1974, Sonja 1988, Andrea 1994, Sven 1995, Olaf 1997, Tom 2000, Tim 2004, Tina 2010\nOracle 19c: WITH Nachkommen(Name) AS (… UNION ALL …) ohne RECURSIVE – oder:\nSELECT Kind FROM Elternteil START WITH Elternteil = 'Albert' CONNECT BY PRIOR Kind = Elternteil;", db: 'fam', sql: "WITH RECURSIVE Nachkommen(Name) AS (SELECT Kind FROM Elternteil WHERE Elternteil = 'Albert' UNION SELECT e.Kind FROM Elternteil e JOIN Nachkommen n ON e.Elternteil = n.Name) SELECT p.Name, p.Geburtsjahr FROM Nachkommen n JOIN Person p ON p.Name = n.Name ORDER BY p.Geburtsjahr", ordered: true },
    ] },
  { id: 'p6', nr: '#6', titel: 'PL/SQL, Constraints, Trigger, Views', abgabe: '25.11.2026, 20:15', intro: 'Lese- und Ausführungsrechte an dbmi60 weitergeben (GRANT SELECT, GRANT EXECUTE). PL/SQL und Trigger laufen nur in Oracle (DBPRAKT), nicht in der Browser-Konsole – dort gibt es BerechneAlter als nachgebaute Funktion.',
    aufgaben: [
      { nr: '6.1', aufgabe: 'PL/SQL-Funktion BerechneAlter(Person): verstorben → Sterbejahr − Geburtsjahr, lebend → aktuelles Jahr (DBMS-Systemzeit) − Geburtsjahr. Beispiel laut Blatt: Andrea → 30, Albert → 49.', tipp: 'Werte mit SELECT … INTO in Variablen holen. Aktuelles Jahr aus SYSDATE mit EXTRACT. Verzweigung mit IF oder CASE. Prüfe das Andrea-Beispiel nach!', loesung: "CREATE OR REPLACE FUNCTION BerechneAlter (p_name IN VARCHAR2)\nRETURN NUMBER IS\n  v_geb  Person.Geburtsjahr%TYPE;\n  v_tod  Person.Sterbejahr%TYPE;\nBEGIN\n  SELECT Geburtsjahr, Sterbejahr INTO v_geb, v_tod\n  FROM Person WHERE Name = p_name;\n  IF v_tod IS NOT NULL THEN\n    RETURN v_tod - v_geb;\n  ELSE\n    RETURN EXTRACT(YEAR FROM SYSDATE) - v_geb;\n  END IF;\nEND BerechneAlter;\n/\nGRANT EXECUTE ON BerechneAlter TO dbmi60;\nTest: SELECT BerechneAlter('Albert') FROM dual; → 49\nAchtung: Andrea (1994) ergibt 2026 → 32, nicht 30. Das Beispiel auf dem Blatt stammt offenbar aus 2024." },
      { nr: '6.2', aufgabe: 'Schreibe „Welches Familienmitglied hat am längsten gelebt?“ mit BerechneAlter um.', tipp: 'Die Funktion im SELECT und in der Unterabfrage mit MAX verwenden. „Alter“ ist als Alias riskant (ALTER ist ein SQL-Schlüsselwort).', loesung: 'SELECT Name, BerechneAlter(Name) AS Lebensalter FROM Person\nWHERE BerechneAlter(Name) = (SELECT MAX(BerechneAlter(Name)) FROM Person);\n→ 2026: Dagmar (81). Jetzt zählen auch Lebende mit – das Ergebnis hängt vom Jahr ab (Anna verstorben mit 80, Maria wird 2026 80).', db: 'fam', sql: 'SELECT Name, BerechneAlter(Name) AS Lebensalter FROM Person WHERE BerechneAlter(Name) = (SELECT MAX(BerechneAlter(Name)) FROM Person)' },
      { nr: '6.3', aufgabe: 'Ändere den bestehenden Constraint auf NOTE in pruefen (Kemper-Schema), sodass Noten von 1.0 bis 6.0 akzeptiert werden.', tipp: 'Ein CHECK lässt sich nicht „ändern“: alten Constraint finden (Data Dictionary), löschen, neuen anlegen. Der Name ist systemgeneriert (SYS_C…).', loesung: "1) Namen finden:\nSELECT constraint_name, search_condition FROM user_constraints\nWHERE table_name = 'PRUEFEN' AND constraint_type = 'C';\n2) Löschen:\nALTER TABLE pruefen DROP CONSTRAINT SYS_C00xxxxx;  (Name aus Schritt 1)\n3) Neu anlegen – mit eigenem Namen:\nALTER TABLE pruefen ADD CONSTRAINT ck_pruefen_note CHECK (Note BETWEEN 1.0 AND 6.0);\nHinweise: In Schritt 1 erscheinen auch NOT-NULL-Constraints (Typ C). Vorhandene Noten (1, 2, 2) erfüllen den neuen CHECK, sonst schlägt ADD fehl." },
      { nr: '6.4', aufgabe: 'Trigger: Bereits bestandene Prüfungen dürfen nicht wiederholt werden. Note in pruefen darf nur aktualisiert werden, wenn die alte Note schlechter als 4.0 war.', tipp: 'BEFORE UPDATE OF Note ON pruefen FOR EACH ROW. „Schlechter als 4.0“ heißt numerisch > 4.0 – blockieren also bei :old.Note <= 4.0. Entweder Fehler auslösen oder wie keineDegradierung den alten Wert zurücksetzen.', loesung: "CREATE OR REPLACE TRIGGER keineWiederholung\nBEFORE UPDATE OF Note ON pruefen\nFOR EACH ROW\nWHEN (old.Note <= 4.0)\nBEGIN\n  RAISE_APPLICATION_ERROR(-20001,\n    'Prüfung bereits bestanden – Wiederholung nicht erlaubt');\nEND;\n/\nVariante im Stil der VL (still ignorieren statt Fehler):\nBEGIN :new.Note := :old.Note; END;\nTest: UPDATE pruefen SET Note = 1.3 WHERE MatrNr = 28106 AND VorlNr = 5001; → Fehler (alte Note 1.0)\nIn WHEN ohne Doppelpunkt (old.Note), im Rumpf mit (:old.Note)." },
      { nr: '6.5', aufgabe: 'View im Kemper-Schema: MatrNr jedes Studenten mit Notendurchschnitt – auch Studenten ohne Prüfung.', tipp: '„Auch ohne Prüfung“ → äußerer Join. AVG ignoriert NULL.', loesung: 'CREATE OR REPLACE VIEW Notendurchschnitt AS\nSELECT s.MatrNr, AVG(p.Note) AS Durchschnitt\nFROM Studenten s LEFT OUTER JOIN pruefen p ON s.MatrNr = p.MatrNr\nGROUP BY s.MatrNr;\nGRANT SELECT ON Notendurchschnitt TO dbmi60;\n→ 8 Tupel: 25403 2 · 27550 2 · 28106 1 · alle anderen NULL\nNicht update-fähig (Aggregation).', db: 'uni', sql: 'SELECT s.MatrNr, AVG(p.Note) AS Durchschnitt FROM Studenten s LEFT OUTER JOIN pruefen p ON s.MatrNr = p.MatrNr GROUP BY s.MatrNr' },
    ] },
];

/* SQL-Training für die Konsole (Uni-DB), steigender Schwierigkeitsgrad. */
const DRILL = [
  { id: 'd01', lv: 1, db: 'uni', t: 'Namen und Fachgebiet aller Assistenten von Sokrates.', h: 'Join Assistenten–Professoren über Boss = PersNr.', sql: "SELECT a.Name, a.Fachgebiet FROM Assistenten a JOIN Professoren p ON a.Boss = p.PersNr WHERE p.Name = 'Sokrates'", e: 'Platon (Ideenlehre), Aristoteles (Syllogistik).' },
  { id: 'd02', lv: 1, db: 'uni', t: 'Alle Vorlesungen mit 3 oder mehr SWS, sortiert nach SWS absteigend, dann Titel aufsteigend.', h: 'WHERE + ORDER BY mit zwei Kriterien.', sql: 'SELECT * FROM Vorlesungen WHERE SWS >= 3 ORDER BY SWS DESC, Titel ASC', e: 'Die 3 Kritiken, Ethik, Grundzüge, Logik (4 SWS), dann Erkenntnistheorie, Wissenschaftstheorie (3 SWS).', ordered: true },
  { id: 'd03', lv: 1, db: 'uni', t: 'Studenten zwischen dem 3. und 10. Semester (inklusive).', h: 'BETWEEN schließt beide Grenzen ein.', sql: 'SELECT * FROM Studenten WHERE Semester BETWEEN 3 AND 10', e: 'Fichte (10), Aristoxenos (8), Schopenhauer (6), Carnap (3).' },
  { id: 'd04', lv: 1, db: 'uni', t: 'Anzahl der Studenten pro Semester, nur Semester mit mehr als einem Studenten.', h: 'GROUP BY + HAVING.', sql: 'SELECT Semester, count(*) AS Anzahl FROM Studenten GROUP BY Semester HAVING count(*) > 1', e: 'Nur Semester 2 mit 2 Studenten.' },
  { id: 'd05', lv: 1, db: 'uni', t: 'Welche Studenten hören welche Vorlesungen? (Name, Titel)', h: '3-Wege-Join Studenten–hoeren–Vorlesungen.', sql: 'SELECT s.Name, v.Titel FROM Studenten s JOIN hoeren h ON s.MatrNr = h.MatrNr JOIN Vorlesungen v ON h.VorlNr = v.VorlNr', e: '13 Tupel – eines pro hoeren-Tupel.' },
  { id: 'd06', lv: 2, db: 'uni', t: 'Jeder Professor mit der Anzahl seiner Vorlesungen – auch Professoren ohne Vorlesung (dann 0).', h: 'LEFT OUTER JOIN. Welches count zählt NULL nicht mit?', sql: 'SELECT p.PersNr, p.Name, count(v.VorlNr) AS Anzahl FROM Professoren p LEFT OUTER JOIN Vorlesungen v ON v.gelesenVon = p.PersNr GROUP BY p.PersNr, p.Name', e: 'Sokrates 3, Russel 3, Kant 2, Popper 1, Augustinus 1, Kopernikus 0, Curie 0. Mit count(*) stünde bei Kopernikus und Curie fälschlich 1.' },
  { id: 'd07', lv: 2, db: 'uni', t: 'Vorlesungen, die niemand hört (Titel).', h: 'NOT EXISTS oder LEFT JOIN … IS NULL.', sql: 'SELECT Titel FROM Vorlesungen v WHERE NOT EXISTS (SELECT * FROM hoeren h WHERE h.VorlNr = v.VorlNr)', e: 'Erkenntnistheorie, Die 3 Kritiken.' },
  { id: 'd08', lv: 2, db: 'uni', t: 'Vorlesungen mit mehr SWS als alle Vorlesungen von Russel.', h: '> ALL mit Unterabfrage.', sql: "SELECT Titel, SWS FROM Vorlesungen WHERE SWS > ALL (SELECT v.SWS FROM Vorlesungen v JOIN Professoren p ON v.gelesenVon = p.PersNr WHERE p.Name = 'Russel')", e: 'Russel liest 3, 3, 2 SWS → alle mit 4 SWS: Grundzüge, Ethik, Logik, Die 3 Kritiken. SQLite kennt kein ALL – in der Konsole daher mit > (SELECT max(…)) prüfen.', alt: "SELECT Titel, SWS FROM Vorlesungen WHERE SWS > (SELECT max(v.SWS) FROM Vorlesungen v JOIN Professoren p ON v.gelesenVon = p.PersNr WHERE p.Name = 'Russel')" },
  { id: 'd09', lv: 2, db: 'uni', t: 'Gesamt-SWS pro Student (Name) – auch Studenten, die nichts hören (dann 0).', h: 'LEFT JOIN über zwei Relationen + COALESCE.', sql: 'SELECT s.Name, COALESCE(sum(v.SWS), 0) AS SWS FROM Studenten s LEFT JOIN hoeren h ON s.MatrNr = h.MatrNr LEFT JOIN Vorlesungen v ON h.VorlNr = v.VorlNr GROUP BY s.MatrNr, s.Name', e: 'Carnap 11, Theophrastos 10, Schopenhauer 8, Feuerbach 6, Fichte 4, Jonas 2, Xenokrates 0, Aristoxenos 0.' },
  { id: 'd10', lv: 2, db: 'uni', t: 'Paare von Studenten im selben Semester – jedes Paar nur einmal.', h: 'Self Join mit s1.MatrNr < s2.MatrNr.', sql: 'SELECT s1.Name, s2.Name FROM Studenten s1 JOIN Studenten s2 ON s1.Semester = s2.Semester AND s1.MatrNr < s2.MatrNr', e: '(Theophrastos, Feuerbach). Mit <> statt < käme das Paar doppelt.' },
  { id: 'd11', lv: 2, db: 'uni', t: 'Prüfungen, die besser als der Durchschnitt verlaufen sind.', h: 'Unkorrelierte Unterabfrage im WHERE (Folie 28).', sql: 'SELECT * FROM pruefen WHERE Note < (SELECT avg(Note) FROM pruefen)', e: 'Durchschnitt 1,67 → nur Carnap (28106, Note 1).' },
  { id: 'd12', lv: 2, db: 'uni', t: 'Professoren (Name), die prüfen, aber keine Assistenten haben.', h: 'Zwei Bedingungen: EXISTS in pruefen und NOT EXISTS in Assistenten.', sql: 'SELECT p.Name FROM Professoren p WHERE EXISTS (SELECT * FROM pruefen x WHERE x.PersNr = p.PersNr) AND NOT EXISTS (SELECT * FROM Assistenten a WHERE a.Boss = p.PersNr)', e: 'Prüfer: Russel, Sokrates, Kant. Davon ohne Assistenten: Kant.' },
  { id: 'd13', lv: 3, db: 'uni', t: 'Professoren mit der größten Anzahl an Assistenten (Name, Anzahl).', h: 'Gruppieren, dann mit dem Maximum der Gruppenzählungen vergleichen (Unterabfrage im FROM oder HAVING >= ALL).', sql: 'SELECT p.Name, count(*) AS Anzahl FROM Professoren p JOIN Assistenten a ON a.Boss = p.PersNr GROUP BY p.PersNr, p.Name HAVING count(*) = (SELECT max(c) FROM (SELECT count(*) AS c FROM Assistenten GROUP BY Boss) t)', e: 'Sokrates, Russel, Kopernikus mit je 2.' },
  { id: 'd14', lv: 3, db: 'uni', t: 'Studenten (Name), die mindestens eine Vorlesung von Sokrates UND eine von Kant hören.', h: 'Zwei EXISTS oder INTERSECT.', sql: "SELECT s.Name FROM Studenten s WHERE EXISTS (SELECT * FROM hoeren h JOIN Vorlesungen v ON h.VorlNr = v.VorlNr JOIN Professoren p ON v.gelesenVon = p.PersNr WHERE h.MatrNr = s.MatrNr AND p.Name = 'Sokrates') AND EXISTS (SELECT * FROM hoeren h JOIN Vorlesungen v ON h.VorlNr = v.VorlNr JOIN Professoren p ON v.gelesenVon = p.PersNr WHERE h.MatrNr = s.MatrNr AND p.Name = 'Kant')", e: 'Schopenhauer (Logik + Grundzüge), Theophrastos (Ethik/Mäeutik + Grundzüge).' },
  { id: 'd15', lv: 3, db: 'uni', t: 'Studenten (Name), die ALLE Vorlesungen hören, die Theophrastos hört.', h: 'Doppeltes NOT EXISTS – der Divisor ist „Vorlesungen von Theophrastos“.', sql: "SELECT s.Name FROM Studenten s WHERE NOT EXISTS (SELECT * FROM hoeren t JOIN Studenten x ON t.MatrNr = x.MatrNr WHERE x.Name = 'Theophrastos' AND NOT EXISTS (SELECT * FROM hoeren h WHERE h.MatrNr = s.MatrNr AND h.VorlNr = t.VorlNr))", e: 'Nur Theophrastos selbst (5001, 5041, 5049 hört sonst niemand komplett).' },
  { id: 'd16', lv: 3, db: 'uni', t: 'Professoren mit Lehrbelastung (Summe SWS) und durchschnittlicher Lehrbelastung aller lesenden Professoren.', h: 'Korrelierte Unterabfrage im SELECT wie Folie 31; nur Professoren mit Vorlesungen.', sql: 'SELECT p.PersNr, p.Name, (SELECT sum(SWS) FROM Vorlesungen WHERE gelesenVon = p.PersNr) AS Lehrbelastung, (SELECT sum(SWS) * 1.0 / count(DISTINCT gelesenVon) FROM Vorlesungen) AS Durchschnitt FROM Professoren p WHERE EXISTS (SELECT * FROM Vorlesungen WHERE gelesenVon = p.PersNr)', e: 'Sokrates 10, Russel 8, Kant 8, Popper 2, Augustinus 2; Durchschnitt 30 / 5 = 6.' },
  { id: 'd17', lv: 3, db: 'uni', t: 'Alle direkten und indirekten Nachfolger von „Grundzüge“ (Titel).', h: 'WITH RECURSIVE über voraussetzen, diesmal in Richtung Nachfolger.', sql: 'WITH RECURSIVE nach(VorlNr) AS (SELECT Nachfolger FROM voraussetzen WHERE Vorgaenger = 5001 UNION SELECT v.Nachfolger FROM voraussetzen v JOIN nach ON v.Vorgaenger = nach.VorlNr) SELECT Titel FROM Vorlesungen WHERE VorlNr IN (SELECT VorlNr FROM nach)', e: 'Ethik, Erkenntnistheorie, Mäeutik, Bioethik, Wissenschaftstheorie, Der Wiener Kreis.' },
  { id: 'd18', lv: 3, db: 'uni', t: 'Für jeden Rang: Anzahl Professoren und Anzahl der von ihnen gehaltenen Vorlesungen.', h: 'Zwei verschiedene Zählungen → count(DISTINCT …) nach dem LEFT JOIN.', sql: 'SELECT p.Rang, count(DISTINCT p.PersNr) AS Profs, count(v.VorlNr) AS Vorlesungen FROM Professoren p LEFT JOIN Vorlesungen v ON v.gelesenVon = p.PersNr GROUP BY p.Rang', e: 'C3: 3 Profs, 2 Vorlesungen · C4: 4 Profs, 8 Vorlesungen.' },
];

